def _file_fix_strategy(
    reason: str,
) -> tuple[OCRFixAction, str, tuple[str, ...]]:
    lowered = reason.casefold()
    if "pages_total" in lowered:
        return (
            "reconcile_manifest",
            "Reconcile the sidecar page manifest with the source document.",
            (
                "Compare pages_total and page slots with the source page count.",
                "Regenerate missing or inconsistent page records from the source.",
                "Publish the corrected manifest and re-audit it.",
            ),
        )
    if any(
        marker in lowered
        for marker in (
            "cannot read layout sidecar",
            "sidecar root",
            "no valid pages list",
            "page slot",
            "region slot",
        )
    ):
        return (
            "rebuild_sidecar",
            "Recover or rebuild the structured layout sidecar before repairing regions.",
            (
                "Restore the newest valid partial checkpoint when one exists.",
                "Otherwise rerun layout detection from the source document.",
                "Atomically publish and re-audit the replacement sidecar.",
            ),
        )
    if (
        any(
            marker in lowered
            for marker in (
                "document status",
                "partial pages",
                "page status",
                "status is 'processing'",
                "status is 'pending'",
            )
        )
        or (
            lowered.startswith("page ")
            and any(
                marker in lowered
                for marker in (" status is ", "has no valid regions list", ": ")
            )
        )
    ):
        return (
            "resume_document",
            "Resume the incomplete document from its durable checkpoint.",
            (
                "Resolve unfinished pages and regions from the sidecar.",
                "Resume with the recorded OCR and layout settings.",
                "Preserve completed regions, publish, and re-audit.",
            ),
        )
    return (
        "manual_review",
        "Inspect the file-level inconsistency before attempting region repair.",
        (
            "Compare the source, Markdown, final sidecar, and partial checkpoint.",
            "Record the corrected document state and run the audit again.",
        ),
    )


def _region_fix_strategy(
    issue: OCRRegionQualityIssue,
) -> tuple[OCRFixAction, str, tuple[str, ...]]:
    lowered = " ".join(issue.reasons).casefold()
    if any(
        marker in lowered
        for marker in ("duplicate region index", "region index", "bbox")
    ):
        return (
            "rerun_layout_detection",
            "Repair region identity or geometry before retrying OCR.",
            (
                "Re-render the source page at the recorded DPI.",
                "Rerun layout detection and reconcile neighboring region indexes.",
                "Replace the bbox/index, regenerate its crop, and re-audit.",
            ),
        )
    if (
        "asset is missing" in lowered
        or "no referenced crop asset" in lowered
    ):
        return (
            "regenerate_crop",
            "Regenerate the missing region crop before OCR retry.",
            (
                "Render the source page and crop the recorded bbox.",
                "Verify the crop is non-empty and stored beside the sidecar.",
                "Retry OCR on the regenerated crop and validate the response.",
            ),
        )
    if issue.issue_kind == "recovered":
        return (
            "verify_recovery",
            "Verify the recovered prefix or fallback before accepting it as final.",
            (
                "Compare recovered content with the crop and available native PDF text.",
                "Accept it only when semantic and structural checks agree.",
                "Otherwise requeue the original crop for OCR.",
            ),
        )
    if any(
        marker in lowered
        for marker in (
            "token limit",
            "output-token limit",
            "unbalanced html table",
        )
    ):
        return (
            "split_and_stitch",
            "Split the oversized or truncated region and stitch validated OCR tiles.",
            (
                "Prefer aligned native PDF text when a reliable text layer exists.",
                "Otherwise tile the crop with overlap along rows or reading order.",
                "OCR each tile, stitch the result, and validate structure and repetition.",
            ),
        )
    if any(
        marker in lowered
        for marker in (
            "degenerate",
            "repeated image placeholder",
            "evaluator commentary",
            "control token",
            "pathological",
            "abnormal finish reason",
        )
    ):
        return (
            "discard_and_reprocess",
            "Quarantine the untrustworthy OCR content and reprocess the original crop.",
            (
                "Keep the current content only as provenance; exclude it from retrieval.",
                "Retry from the crop or aligned native PDF text, preferably with an alternate model.",
                "Accept only output that passes repetition, markup, and leakage checks.",
            ),
        )
    if any(
        marker in lowered
        for marker in (
            "no usable ocr content",
            "no usable text",
            "empty response",
            "empty after post-processing",
        )
    ):
        if issue.label in {"footer", "header", "number"}:
            return (
                "review_or_discard",
                "Decide whether this empty decorative region needs OCR at all.",
                (
                    "Inspect the crop and its neighboring reading-order regions.",
                    "If decorative or truly empty, record an intentional discard.",
                    "Otherwise expand or enhance the crop and retry OCR.",
                ),
            )
        return (
            "adjust_crop_and_retry",
            "Improve the crop signal and retry the empty OCR region.",
            (
                "Inspect whether the region is meaningful rather than decorative.",
                "Expand the bbox slightly and adjust resolution or contrast.",
                "Retry OCR; preserve the crop for manual review if it remains empty.",
            ),
        )
    if issue.issue_kind == "incomplete":
        return (
            "resume_region",
            "Resume this pending or interrupted region from the checkpoint.",
            (
                "Confirm the region crop and recorded settings are still compatible.",
                "Retry only this region without overwriting completed neighbors.",
                "Publish the updated sidecar and re-audit the page.",
            ),
        )
    if issue.issue_kind == "failed":
        return (
            "retry_region",
            "Retry the failed region while retaining the original error as provenance.",
            (
                "Verify service availability, crop readability, and request settings.",
                "Retry with bounded backoff and the same region identity.",
                "Validate the replacement before clearing the failure.",
            ),
        )
    if issue.issue_kind == "suspicious_completed":
        return (
            "discard_and_reprocess",
            "Treat the suspicious completed output as untrusted and reprocess it.",
            (
                "Exclude the current content from downstream retrieval.",
                "Reprocess from the original crop or native PDF text.",
                "Require a clean audit before restoring completed status.",
            ),
        )
    return (
        "manual_review",
        "Inspect the region and choose a repair method manually.",
        ("Compare the crop, OCR content, and neighboring regions.",),
    )


def propose_ocr_repairs(
    ocr_repair_queue: Sequence[OCRFileQualityReport],
) -> list[OCRFixProposal]:
    """Return one deterministic fix proposal per file reason and region issue."""
    proposals: list[OCRFixProposal] = []
    for report in sorted(
        ocr_repair_queue, key=lambda item: str(item.sidecar_path).casefold()
    ):
        for reason in report.file_reasons:
            action, summary, steps = _file_fix_strategy(reason)
            proposals.append(
                OCRFixProposal(
                    sidecar_path=report.sidecar_path,
                    source_path=report.source_path,
                    scope="file",
                    action=action,
                    summary=summary,
                    steps=steps,
                    reasons=(reason,),
                    page_number=None,
                    region_index=None,
                    label=None,
                    task_type=None,
                    bbox=None,
                    asset_path=None,
                )
            )
        for issue in report.region_issues:
            action, summary, steps = _region_fix_strategy(issue)
            proposals.append(
                OCRFixProposal(
                    sidecar_path=report.sidecar_path,
                    source_path=report.source_path,
                    scope="region",
                    action=action,
                    summary=summary,
                    steps=steps,
                    reasons=issue.reasons,
                    page_number=issue.page_number,
                    region_index=issue.region_index,
                    label=issue.label,
                    task_type=issue.task_type,
                    bbox=issue.bbox,
                    asset_path=issue.asset_path,
                )
            )
    return proposals


def build_ocr_repair_plan(
    root: str | Path,
    *,
    include_partial_checkpoints: bool = False,
) -> list[OCRFixProposal]:
    """Audit a result tree and return proposals for its repair queue."""
    return propose_ocr_repairs(
        collect_ocr_repair_queue(
            root,
            include_partial_checkpoints=include_partial_checkpoints,
        )
    )


@dataclass(frozen=True)
class OCRSplitTile:
    """One overlapping vertical crop used to retry an oversized OCR region."""

    index: int
    top: int
    bottom: int
    image: Image.Image


@dataclass(frozen=True)
class OCRSplitFragment:
    """Validated OCR output and provider metadata for one split tile."""

    raw_content: str
    content: str
    finish_reason: str | None
    metadata: Mapping[str, Any]


OCRSplitRecognizer = Callable[
    [Image.Image, OCRFixProposal, OCRSplitTile],
    Awaitable[OCRSplitFragment],
]
OCRSplitMarkdownRenderer = Callable[[dict[str, Any]], str]


def _split_boundary_scores(image: Image.Image) -> list[int]:
    grayscale = image.convert("L")
    probe_width = min(grayscale.width, 256)
    if probe_width != grayscale.width:
        grayscale = grayscale.resize(
            (probe_width, grayscale.height), Image.Resampling.BILINEAR
        )
    pixels = list(grayscale.get_flattened_data())
    return [
        sum(255 - value for value in pixels[offset : offset + probe_width])
        for offset in range(0, len(pixels), probe_width)
    ]


def split_layout_region_image(
    image: Image.Image,
    *,
    tile_height: int = 1400,
    overlap: int = 96,
    boundary_search: int = 128,
) -> tuple[OCRSplitTile, ...]:
    """Split a tall OCR crop near low-ink rows while retaining overlap."""
    if image.width <= 0 or image.height <= 1:
        raise ValueError("split-and-stitch requires a non-empty image")
    if tile_height <= 1:
        raise ValueError("tile_height must be greater than one")
    if overlap < 0 or overlap >= tile_height:
        raise ValueError("overlap must be non-negative and smaller than tile_height")
    if boundary_search < 0:
        raise ValueError("boundary_search must be non-negative")

    usable_height = max(1, tile_height - overlap)
    tile_count = max(1, math.ceil((image.height - overlap) / usable_height))
    tile_count = min(tile_count, image.height)
    nominal_height = image.height / tile_count
    scores = _split_boundary_scores(image)
    boundaries: list[int] = []
    previous = 0
    for boundary_index in range(1, tile_count):
        ideal = round(boundary_index * nominal_height)
        remaining = tile_count - boundary_index
        minimum = max(previous + 1, ideal - boundary_search)
        maximum = min(image.height - remaining, ideal + boundary_search)
        if minimum > maximum:
            boundary = min(image.height - remaining, max(previous + 1, ideal))
        else:
            boundary = min(
                range(minimum, maximum + 1),
                key=lambda row: (scores[row], abs(row - ideal)),
            )
        boundaries.append(boundary)
        previous = boundary

    half_overlap = overlap // 2
    tiles: list[OCRSplitTile] = []
    for index in range(tile_count):
        top = 0 if index == 0 else max(0, boundaries[index - 1] - half_overlap)
        bottom = (
            image.height
            if index == tile_count - 1
            else min(image.height, boundaries[index] + overlap - half_overlap)
        )
        if bottom <= top:
            raise ValueError("split-and-stitch produced an empty tile")
        tiles.append(
            OCRSplitTile(
                index=index,
                top=top,
                bottom=bottom,
                image=image.crop((0, top, image.width, bottom)),
            )
        )
    return tuple(tiles)


_TABLE_OPEN_RE = re.compile(r"(?is)<table\b[^>]*>")
_TABLE_ROW_RE = re.compile(r"(?is)<tr\b[^>]*>.*?</tr>")


def _split_row_signature(row: str) -> str:
    without_tags = re.sub(r"(?is)<[^>]+>", " ", row)
    return re.sub(r"\s+", " ", html.unescape(without_tags)).strip().casefold()


def _split_units_overlap(existing: Sequence[str], incoming: Sequence[str]) -> int:
    for size in range(min(len(existing), len(incoming)), 0, -1):
        matched = True
        for left, right in zip(existing[-size:], incoming[:size], strict=True):
            left_signature = _split_row_signature(left)
            right_signature = _split_row_signature(right)
            if not left_signature or not right_signature:
                matched = False
                break
            if min(len(left_signature), len(right_signature)) < 8:
                similar = left_signature == right_signature
            else:
                similar = (
                    SequenceMatcher(
                        None, left_signature, right_signature, autojunk=False
                    ).ratio()
                    >= 0.90
                )
            if not similar:
                matched = False
                break
        if matched:
            return size
    return 0


def stitch_split_ocr_content(
    fragments: Sequence[str], *, task_type: str
) -> str:
    """Stitch overlapping OCR fragments and remove duplicate boundary units."""
    cleaned = [str(fragment).strip() for fragment in fragments if str(fragment).strip()]
    if not cleaned:
        raise ValueError("split-and-stitch returned no usable OCR fragments")

    if task_type == "table":
        fragment_rows = [tuple(_TABLE_ROW_RE.findall(fragment)) for fragment in cleaned]
        if all(fragment_rows):
            rows: list[str] = []
            for incoming in fragment_rows:
                rows.extend(incoming[_split_units_overlap(rows, incoming) :])
            opening_match = _TABLE_OPEN_RE.search(cleaned[0])
            opening = opening_match.group(0) if opening_match else "<table>"
            return opening + "".join(rows) + "</table>"
        if any(fragment_rows):
            raise ValueError(
                "split-and-stitch cannot mix HTML-row and plain-text table fragments"
            )

    units: list[str] = []
    for fragment in cleaned:
        incoming = [line for line in fragment.splitlines() if line.strip()]
        units.extend(incoming[_split_units_overlap(units, incoming) :])
    stitched = "\n".join(units).strip()
    if not stitched:
        raise ValueError("split-and-stitch produced empty stitched content")
    return stitched


def _publish_split_repair_pair(
    sidecar_path: Path,
    markdown_path: Path,
    layout: dict[str, Any],
    markdown: str,
) -> None:
    """Atomically publish a repaired sidecar and reconstructed Markdown."""
    markdown_path.parent.mkdir(parents=True, exist_ok=True)
    with TemporaryDirectory(
        dir=markdown_path.parent,
        prefix=f".{markdown_path.stem}.split-repair-",
    ) as temporary_directory:
        stage_root = Path(temporary_directory)
        staged_sidecar = stage_root / sidecar_path.name
        staged_markdown = stage_root / markdown_path.name
        staged_sidecar.write_text(
            json.dumps(layout, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        staged_markdown.write_text(markdown, encoding="utf-8", newline="\n")
        publications = (
            (staged_sidecar, sidecar_path),
            (staged_markdown, markdown_path),
        )
        backups: list[tuple[Path, Path]] = []
        published: list[tuple[Path, Path]] = []
        try:
            for index, (_, destination) in enumerate(publications):
                if destination.exists():
                    backup = stage_root / f"backup-{index}"
                    destination.replace(backup)
                    backups.append((backup, destination))
            for staged, destination in publications:
                staged.replace(destination)
                published.append((destination, staged))
        except Exception:
            for destination, staged in reversed(published):
                if destination.exists():
                    destination.replace(staged)
            for backup, destination in reversed(backups):
                if backup.exists():
                    backup.replace(destination)
            raise


def _split_repair_region(
    layout: dict[str, Any], proposal: OCRFixProposal
) -> tuple[dict[str, Any], dict[str, Any]]:
    pages = {
        int(page.get("page_number", position)): page
        for position, page in enumerate(layout.get("pages", []), start=1)
        if isinstance(page, dict)
    }
    page = pages.get(int(proposal.page_number or 0))
    if page is None:
        raise ValueError(f"split-and-stitch page is missing for {proposal}")
    region = next(
        (
            item
            for item in page.get("regions", [])
            if isinstance(item, dict)
            and int(item.get("index", -1)) == proposal.region_index
        ),
        None,
    )
    if region is None:
        raise ValueError(f"split-and-stitch region is missing for {proposal}")
    return page, region


async def _recognize_adaptive_split_tile(
    tile: OCRSplitTile,
    proposal: OCRFixProposal,
    recognize_tile: OCRSplitRecognizer,
    *,
    overlap: int,
    boundary_search: int,
    min_tile_height: int,
    max_split_depth: int,
    depth: int = 0,
) -> tuple[tuple[OCRSplitTile, OCRSplitFragment, int], ...]:
    """Recursively shrink tiles with truncated or invalid OCR output."""
    fragment = await recognize_tile(tile.image, proposal, tile)
    fragment_record = {
        "status": "completed",
        "task_type": proposal.task_type or "text",
        "content": fragment.content,
        "error": None,
        "recovery": None,
        "finish_reason": fragment.finish_reason,
        "asset": None,
    }
    validation_reasons = _completed_layout_quality_reasons(
        fragment_record,
        sidecar_path=proposal.sidecar_path,
    )
    if not validation_reasons:
        return ((tile, fragment, depth),)
    if depth >= max_split_depth or tile.image.height <= min_tile_height:
        raise ValueError(
            f"split tile y={tile.top}:{tile.bottom} failed validation at "
            f"depth {depth}: {'; '.join(validation_reasons)}"
        )

    child_tile_height = max(
        min_tile_height,
        math.ceil((tile.image.height + overlap) / 2),
    )
    child_tile_height = min(child_tile_height, tile.image.height - 1)
    children = split_layout_region_image(
        tile.image,
        tile_height=child_tile_height,
        overlap=overlap,
        boundary_search=boundary_search,
    )
    positioned_children = tuple(
        OCRSplitTile(
            index=child.index,
            top=tile.top + child.top,
            bottom=tile.top + child.bottom,
            image=child.image,
        )
        for child in children
    )
    nested = await asyncio.gather(
        *(
            _recognize_adaptive_split_tile(
                child,
                proposal,
                recognize_tile,
                overlap=overlap,
                boundary_search=boundary_search,
                min_tile_height=min_tile_height,
                max_split_depth=max_split_depth,
                depth=depth + 1,
            )
            for child in positioned_children
        )
    )
    return tuple(item for group in nested for item in group)


async def split_and_stitch_layout_regions(
    report: OCRFileQualityReport,
    proposals: Sequence[OCRFixProposal],
    recognize_tile: OCRSplitRecognizer,
    render_markdown: OCRSplitMarkdownRenderer,
    *,
    tile_height: int = 1400,
    overlap: int = 96,
    boundary_search: int = 128,
    min_tile_height: int = 320,
    max_split_depth: int = 4,
) -> str:
    """Repair token-limited regions with adaptive validated OCR tiles."""
    if min_tile_height <= overlap:
        raise ValueError("min_tile_height must be greater than overlap")
    if max_split_depth < 0:
        raise ValueError("max_split_depth must be non-negative")
    selected = [
        proposal
        for proposal in proposals
        if proposal.scope == "region"
        and proposal.action in {"split_and_stitch", "split_and_retry"}
    ]
    if not selected:
        raise ValueError("split-and-stitch handler received no matching proposal")

    sidecar_path = report.sidecar_path.expanduser().resolve()
    state_path = _layout_repair_state_path(sidecar_path)
    layout = json.loads(state_path.read_text(encoding="utf-8"))
    if not isinstance(layout, dict):
        raise ValueError(f"layout repair state must be an object: {state_path}")

    repaired_keys: list[tuple[int, int]] = []
    repaired_tile_count = 0
    for proposal in selected:
        page, region = _split_repair_region(layout, proposal)
        crop_path = proposal.asset_path
        if crop_path is None or not crop_path.is_file():
            raise FileNotFoundError(f"split-and-stitch crop is unavailable for {proposal}")
        with Image.open(crop_path) as opened:
            crop = opened.convert("RGB")
        tiles = split_layout_region_image(
            crop,
            tile_height=tile_height,
            overlap=overlap,
            boundary_search=boundary_search,
        )

        recognized_groups = await asyncio.gather(
            *(
                _recognize_adaptive_split_tile(
                    tile,
                    proposal,
                    recognize_tile,
                    overlap=overlap,
                    boundary_search=boundary_search,
                    min_tile_height=min_tile_height,
                    max_split_depth=max_split_depth,
                )
                for tile in tiles
            )
        )
        recognized = [item for group in recognized_groups for item in group]
        tiles = tuple(
            OCRSplitTile(index=index, top=tile.top, bottom=tile.bottom, image=tile.image)
            for index, (tile, _, _) in enumerate(recognized)
        )
        fragments = [fragment for _, fragment, _ in recognized]
        split_depths = [depth for _, _, depth in recognized]
        for tile, fragment in zip(tiles, fragments, strict=True):
            if not fragment.content.strip():
                raise ValueError(f"split tile {tile.index} returned no usable OCR content")
            fragment_record = {
                "status": "completed",
                "task_type": proposal.task_type or region.get("task_type"),
                "content": fragment.content,
                "error": None,
                "recovery": None,
                "finish_reason": fragment.finish_reason,
                "asset": None,
            }
            fragment_reasons = _completed_layout_quality_reasons(
                fragment_record, sidecar_path=sidecar_path
            )
            if fragment_reasons:
                raise ValueError(
                    f"split tile {tile.index} failed validation: "
                    + "; ".join(fragment_reasons)
                )

        task_type = str(proposal.task_type or region.get("task_type") or "text")
        stitched = stitch_split_ocr_content(
            [fragment.content for fragment in fragments], task_type=task_type
        )
        candidate = dict(region)
        candidate.update(
            status="completed",
            raw_content="\n\n".join(
                f"<!-- split tile {tile.index + 1} y={tile.top}:{tile.bottom} -->\n"
                f"{fragment.raw_content}"
                for tile, fragment in zip(tiles, fragments, strict=True)
            ),
            content=stitched,
            error=None,
            recovery=None,
            finish_reason="stop",
        )
        candidate_reasons = _completed_layout_quality_reasons(
            candidate,
            sidecar_path=sidecar_path,
            asset_prefix=layout.get("asset_prefix"),
        )
        if candidate_reasons:
            raise ValueError(
                "stitched split-and-stitch output failed validation: "
                + "; ".join(candidate_reasons)
            )

        history = region.setdefault("repair_history", [])
        if not isinstance(history, list):
            raise ValueError(f"region repair_history is invalid for {proposal}")
        history.append(
            {
                "action": proposal.action,
                "status": region.get("status"),
                "raw_content": region.get("raw_content"),
                "content": region.get("content"),
                "error": region.get("error"),
                "recovery": region.get("recovery"),
                "finish_reason": region.get("finish_reason"),
                "reasons": list(proposal.reasons),
            }
        )
        for key in ("response_id", "usage", "elapsed_s", "input_mime_type"):
            region.pop(key, None)
        region.update(candidate)
        region["split_repair"] = {
            "version": 2,
            "tile_height": tile_height,
            "overlap": overlap,
            "boundary_search": boundary_search,
            "min_tile_height": min_tile_height,
            "max_split_depth": max_split_depth,
            "tiles": [
                {
                    "index": tile.index,
                    "top": tile.top,
                    "bottom": tile.bottom,
                    "split_depth": split_depth,
                    "finish_reason": fragment.finish_reason,
                    "response_id": fragment.metadata.get("response_id"),
                    "usage": dict(fragment.metadata.get("usage") or {}),
                    "elapsed_s": fragment.metadata.get("elapsed_s"),
                }
                for tile, fragment, split_depth in zip(
                    tiles, fragments, split_depths, strict=True
                )
            ],
        }
        page["status"] = (
            "completed"
            if all(
                isinstance(item, dict)
                and item.get("status") in _OCR_TERMINAL_REGION_STATUSES
                and not item.get("error")
                for item in page.get("regions", [])
            )
            else "partial"
        )
        if page["status"] == "completed":
            page["error"] = None
        repaired_keys.append(
            (int(proposal.page_number or 0), int(proposal.region_index or 0))
        )
        repaired_tile_count += len(tiles)

    _refresh_layout_repair_status(layout)
    _publish_layout_repair_state(
        sidecar_path, state_path, layout, render_markdown
    )
    rechecked = audit_layout_ocr_file(sidecar_path)
    remaining_keys = {
        (issue.page_number, issue.region_index) for issue in rechecked.region_issues
    }
    unresolved = [key for key in repaired_keys if key in remaining_keys]
    if unresolved:
        raise RuntimeError(
            f"split-and-stitch output remains in the repair queue: {unresolved}"
        )
    return (
        f"split-and-stitch repaired {len(repaired_keys)} region(s) "
        f"using {repaired_tile_count} tile(s)"
    )


async def split_and_retry_layout_regions(
    report: OCRFileQualityReport,
    proposals: Sequence[OCRFixProposal],
    recognize_tile: OCRSplitRecognizer,
    render_markdown: OCRSplitMarkdownRenderer,
    *,
    tile_height: int = 1400,
    overlap: int = 96,
    boundary_search: int = 128,
    min_tile_height: int = 320,
    max_split_depth: int = 4,
) -> str:
    """Compatibility alias for :func:`split_and_stitch_layout_regions`."""
    return await split_and_stitch_layout_regions(
        report,
        proposals,
        recognize_tile,
        render_markdown,
        tile_height=tile_height,
        overlap=overlap,
        boundary_search=boundary_search,
        min_tile_height=min_tile_height,
        max_split_depth=max_split_depth,
    )

# %% ../../../nbs/03.preprocessing.ocr.audit_repair.ipynb #76db5d53
OCRRepairAttemptStatus = Literal["completed", "failed", "skipped", "dry_run"]
OCRRepairStopReason = Literal[
    "clean",
    "dry_run",
    "no_handlers",
    "execution_failed",
    "no_progress",
    "max_rounds",
]
OCRRepairHandler = Callable[
    [OCRFileQualityReport, tuple[OCRFixProposal, ...]], Awaitable[str | None]
]


@dataclass(frozen=True)
class OCRRepairAttempt:
    """Outcome of dispatching one handler for one OCR result file."""

    sidecar_path: Path
    actions: tuple[OCRFixAction, ...]
    proposal_count: int
    status: OCRRepairAttemptStatus
    message: str
    error: str | None = None


@dataclass(frozen=True)
class OCRRepairRoundResult:
    """One execution pass followed by a fresh audit of every queued file."""

    attempts: tuple[OCRRepairAttempt, ...]
    rechecked_reports: tuple[OCRFileQualityReport, ...]
    remaining_queue: tuple[OCRFileQualityReport, ...]
    remaining_proposals: tuple[OCRFixProposal, ...]
    issues_before: int
    issues_after: int

    @property
    def clean(self) -> bool:
        """Whether the recheck found no remaining repair issue."""
        return not self.remaining_queue


@dataclass(frozen=True)
class OCRRepairLoopResult:
    """Bounded repair rounds and the unresolved queue at the stop condition."""

    rounds: tuple[OCRRepairRoundResult, ...]
    remaining_queue: tuple[OCRFileQualityReport, ...]
    remaining_proposals: tuple[OCRFixProposal, ...]
    stop_reason: OCRRepairStopReason

    @property
    def clean(self) -> bool:
        """Whether all audited findings were repaired."""
        return not self.remaining_queue


def _repair_issue_count(reports: Sequence[OCRFileQualityReport]) -> int:
    return sum(
        len(report.file_reasons) + len(report.region_issues)
        for report in reports
    )


def _repair_progress_counts(values: Sequence[str]) -> str:
    counts = Counter(values)
    return ", ".join(f"{value}={count}" for value, count in sorted(counts.items()))


def _handler_groups(
    proposals: Sequence[OCRFixProposal],
    handlers: Mapping[OCRFixAction, OCRRepairHandler],
) -> tuple[
    list[tuple[OCRRepairHandler, list[OCRFixProposal]]],
    list[OCRFixProposal],
]:
    """Group action aliases that point at the same per-file handler."""
    groups: list[tuple[OCRRepairHandler, list[OCRFixProposal]]] = []
    group_by_identity: dict[int, int] = {}
    unsupported: list[OCRFixProposal] = []
    for proposal in proposals:
        handler = handlers.get(proposal.action)
        if handler is None:
            unsupported.append(proposal)
            continue
        identity = id(handler)
        group_index = group_by_identity.get(identity)
        if group_index is None:
            group_by_identity[identity] = len(groups)
            groups.append((handler, [proposal]))
        else:
            groups[group_index][1].append(proposal)
    return groups, unsupported


_OCR_TERMINAL_REGION_STATUSES = frozenset(
    {"completed", "preserved", "recovered"}
)
_OCR_SELECTIVE_REPROCESS_ACTIONS = frozenset(
    {
        "adjust_crop_and_retry",
        "discard_and_reprocess",
        "regenerate_crop",
        "resume_region",
    }
)
_OCR_REGION_MUTATING_ACTIONS = frozenset(
    {
        *_OCR_SELECTIVE_REPROCESS_ACTIONS,
        "retry_region",
        "review_or_discard",
    }
)


def _repair_markdown_path(sidecar_path: Path) -> Path:
    name = sidecar_path.name.removesuffix(".layout.json") + ".md"
    return sidecar_path.with_name(name)


def _layout_repair_state_path(sidecar_path: Path) -> Path:
    target = _repair_markdown_path(sidecar_path)
    checkpoint = (
        target.parent / f".{target.stem}.layout-work" / "checkpoint.json"
    )
    return checkpoint if checkpoint.is_file() else sidecar_path


def _refresh_layout_repair_status(layout: dict[str, Any]) -> None:
    for page in layout.get("pages", []):
        if not isinstance(page, dict):
            continue
        page["status"] = (
            "completed"
            if all(
                isinstance(region, dict)
                and region.get("status") in _OCR_TERMINAL_REGION_STATUSES
                and not region.get("error")
                for region in page.get("regions", [])
            )
            else "partial"
        )
        if page["status"] == "completed":
            page["error"] = None
    layout["status"] = (
        "processed"
        if all(
            isinstance(page, dict) and page.get("status") == "completed"
            for page in layout.get("pages", [])
        )
        else "partial"
    )
    if layout["status"] == "processed":
        layout.pop("repair_checkpoint", None)


def _write_repair_json(path: Path, payload: dict[str, Any]) -> None:
    temporary_path: Path | None = None
    try:
        with NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            newline="\n",
            dir=path.parent,
            prefix=f".{path.name}.repair-",
            suffix=".tmp",
            delete=False,
        ) as temporary_file:
            json.dump(payload, temporary_file, ensure_ascii=False, indent=2)
            temporary_file.write("\n")
            temporary_path = Path(temporary_file.name)
        temporary_path.replace(path)
        temporary_path = None
    finally:
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)


def _publish_layout_repair_state(
    sidecar_path: Path,
    state_path: Path,
    layout: dict[str, Any],
    render_markdown: OCRSplitMarkdownRenderer,
) -> None:
    if state_path != sidecar_path:
        if layout.get("status") == "processed":
            layout.pop("repair_checkpoint", None)
        else:
            layout["repair_checkpoint"] = str(state_path)
        _write_repair_json(state_path, layout)
    markdown_path = _repair_markdown_path(sidecar_path)
    _publish_split_repair_pair(
        sidecar_path, markdown_path, layout, render_markdown(layout)
    )
    if layout.get("status") == "processed":
        work_root = (
            markdown_path.parent / f".{markdown_path.stem}.layout-work"
        )
        if work_root.exists():
            shutil.rmtree(work_root)
        markdown_path.with_name(
            f"{markdown_path.stem}.partial.md"
        ).unlink(missing_ok=True)
        sidecar_path.with_name(
            f"{markdown_path.stem}.partial.layout.json"
        ).unlink(missing_ok=True)


def _append_layout_repair_history(
    region: dict[str, Any],
    proposal: OCRFixProposal,
    *,
    reasons: Sequence[str] | None = None,
) -> None:
    history = region.setdefault("repair_history", [])
    if not isinstance(history, list):
        raise ValueError(f"Region repair_history is invalid for {proposal}")
    history.append(
        {
            "action": proposal.action,
            "status": region.get("status"),
            "raw_content": region.get("raw_content"),
            "content": region.get("content"),
            "error": region.get("error"),
            "recovery": region.get("recovery"),
            "finish_reason": region.get("finish_reason"),
            "reasons": list(proposal.reasons if reasons is None else reasons),
        }
    )


def _normalized_repair_text(value: object) -> str:
    plain = re.sub(r"<[^>]+>", " ", html.unescape(str(value or "")))
    return "".join(
        character.casefold() for character in plain if character.isalnum()
    )


def _native_region_text(
    pdf_page: Any, page: dict[str, Any], region: dict[str, Any]
) -> str:
    bbox = _quality_bbox(region.get("bbox"))
    if bbox is None:
        raise ValueError("native-PDF repair requires a valid region bbox")
    try:
        page_width = float(page["width"])
        page_height = float(page["height"])
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError("native-PDF repair requires page width and height") from error
    if page_width <= 0 or page_height <= 0:
        raise ValueError("native-PDF repair requires positive page dimensions")
    left, top, right, bottom = bbox
    rectangle = pdf_page.rect
    clip = (
        rectangle.x0 + left / page_width * rectangle.width,
        rectangle.y0 + top / page_height * rectangle.height,
        rectangle.x0 + right / page_width * rectangle.width,
        rectangle.y0 + bottom / page_height * rectangle.height,
    )
    words = pdf_page.get_text("words", clip=clip, sort=True)
    lines: dict[tuple[int, int], list[tuple[int, str]]] = {}
    for word in words:
        if len(word) < 8 or not str(word[4]).strip():
            continue
        lines.setdefault((int(word[5]), int(word[6])), []).append(
            (int(word[7]), str(word[4]))
        )
    return "\n".join(
        " ".join(text for _, text in sorted(line_words))
        for _, line_words in sorted(lines.items())
    ).strip()


def repair_layout_regions_from_native_pdf(
    report: OCRFileQualityReport,
    proposals: Sequence[OCRFixProposal],
    source_path: str | Path,
    render_markdown: OCRSplitMarkdownRenderer,
    *,
    agreement_threshold: float = 0.65,
    skip_unavailable_native_text: bool = False,
) -> str:
    """Verify or replace suspect OCR with spatially aligned native PDF text.

    When ``skip_unavailable_native_text`` is true, regions without a usable
    aligned text layer remain untouched so other repair strategies for the same
    document can still run.
    """
    if not 0 <= agreement_threshold <= 1:
        raise ValueError("agreement_threshold must be between zero and one")
    selected = [
        proposal
        for proposal in proposals
        if proposal.scope == "region"
        and proposal.action in OCR_NATIVE_TEXT_REPAIR_ACTIONS
    ]
    if not selected:
        raise ValueError("native-PDF handler received no matching proposal")

    source = Path(source_path).expanduser().resolve()
    if not source.is_file() or source.suffix.casefold() != ".pdf":
        raise ValueError(f"native-PDF repair requires a PDF source: {source}")
    sidecar_path = report.sidecar_path.expanduser().resolve()
    state_path = _layout_repair_state_path(sidecar_path)
    layout = json.loads(state_path.read_text(encoding="utf-8"))
    if not isinstance(layout, dict):
        raise ValueError(f"layout repair state must be an object: {state_path}")
    pages = {
        int(page.get("page_number", position)): page
        for position, page in enumerate(layout.get("pages", []), start=1)
        if isinstance(page, dict)
    }

    try:
        import fitz
    except ImportError as error:
        raise RuntimeError("PyMuPDF is required for native-PDF repair") from error

    repaired_keys: list[tuple[int, int]] = []
    unavailable: list[str] = []
    verified = 0
    replaced = 0
    with fitz.open(source) as pdf:
        if len(pdf) != int(layout.get("pages_total", len(pages))):
            raise ValueError(
                f"PDF has {len(pdf)} pages but layout has "
                f"{layout.get('pages_total', len(pages))}"
            )
        for proposal in selected:
            page_number = int(proposal.page_number or 0)
            page = pages.get(page_number)
            if page is None:
                raise ValueError(f"native-PDF repair page is missing for {proposal}")
            _, region = _split_repair_region(layout, proposal)
            try:
                native_text = _native_region_text(
                    pdf[page_number - 1], page, region
                )
            except Exception as error:
                if not skip_unavailable_native_text:
                    raise
                unavailable.append(
                    f"page {page_number} region {proposal.region_index}: "
                    f"{type(error).__name__}: {error}"
                )
                continue
            normalized_native = _normalized_repair_text(native_text)
            minimum_characters = (
                1 if str(region.get("label")) in {"header", "footer", "number"} else 2
            )
            if len(normalized_native) < minimum_characters:
                if not skip_unavailable_native_text:
                    raise ValueError(
                        f"native PDF has no usable aligned text for {proposal}"
                    )
                unavailable.append(
                    f"page {page_number} region {proposal.region_index}: "
                    "no usable aligned native PDF text"
                )
                continue
            current_content = str(region.get("content") or "")
            normalized_current = _normalized_repair_text(current_content)
            agreement = (
                SequenceMatcher(
                    None, normalized_current, normalized_native, autojunk=False
                ).ratio()
                if normalized_current
                else 0.0
            )
            use_existing = (
                proposal.action == "verify_recovery"
                and bool(normalized_current)
                and agreement >= agreement_threshold
            )
            replacement = current_content if use_existing else native_text
            candidate = dict(region)
            candidate.update(
                status="completed",
                raw_content=(
                    region.get("raw_content") if use_existing else native_text
                ),
                content=replacement,
                error=None,
                recovery=None,
                finish_reason="stop",
            )
            candidate_reasons = _completed_layout_quality_reasons(
                candidate,
                sidecar_path=sidecar_path,
                asset_prefix=layout.get("asset_prefix"),
            )
            if candidate_reasons:
                if not skip_unavailable_native_text:
                    raise ValueError(
                        f"native-PDF repair failed validation for {proposal}: "
                        + "; ".join(candidate_reasons)
                    )
                unavailable.append(
                    f"page {page_number} region {proposal.region_index}: "
                    + "; ".join(candidate_reasons)
                )
                continue
            _append_layout_repair_history(region, proposal)
            for key in ("response_id", "usage", "elapsed_s", "input_mime_type"):
                region.pop(key, None)
            region.update(candidate)
            region["native_text_repair"] = {
                "version": 1,
                "action": proposal.action,
                "strategy": (
                    "verified_existing_ocr" if use_existing else "native_pdf_replacement"
                ),
                "agreement": agreement,
                "source": str(source),
                "page_number": page_number,
            }
            verified += int(use_existing)
            replaced += int(not use_existing)
            repaired_keys.append((page_number, int(proposal.region_index or 0)))

    if repaired_keys:
        _refresh_layout_repair_status(layout)
        _publish_layout_repair_state(
            sidecar_path, state_path, layout, render_markdown
        )
        rechecked = audit_layout_ocr_file(sidecar_path)
        remaining_keys = {
            (issue.page_number, issue.region_index)
            for issue in rechecked.region_issues
        }
        unresolved = [key for key in repaired_keys if key in remaining_keys]
        if unresolved:
            raise RuntimeError(
                f"native-PDF output remains in the repair queue: {unresolved}"
            )
    return (
        f"native-PDF repaired {len(repaired_keys)} region(s): "
        f"verified={verified}, replaced={replaced}, "
        f"unavailable={len(unavailable)}"
    )


def _clone_repair_assets(source: Path, destination: Path) -> None:
    try:
        shutil.copytree(source, destination, copy_function=os.link)
    except OSError:
        if destination.exists():
            shutil.rmtree(destination)
        shutil.copytree(source, destination, copy_function=shutil.copy2)


def stage_layout_ocr_repairs(
    report: OCRFileQualityReport,
    proposals: Sequence[OCRFixProposal],
    source_path: str | Path,
) -> dict[str, Any]:
    """Atomically stage checkpoint-compatible region repairs for one file.

    The source path may be relocated only when its size, nanosecond mtime, and
    recorded SHA-256 digest match. A legacy hashless signature can be upgraded
    only while the source remains at its recorded path. Every region selected
    for a mutating
    retry or discard archives its previous response exactly once in
    ``repair_history``. A document-resume proposal also archives nonterminal
    regions that have no more-specific region proposal. Terminal regions
    selected for crop adjustment, quarantine/reprocessing, crop regeneration,
    or region resume are reopened after their evidence is archived.
    Empty decorative regions selected for review are intentionally discarded.
    Other proposal
    actions keep their current region state for the provider's normal resume
    behavior. The published sidecar is marked partial without replacing its
    region payload, allowing the provider to enter its resume path. The OCR
    provider remains responsible for publishing the staged checkpoint and
    reconstructed Markdown.
    """
    source = Path(source_path).expanduser().resolve()
    if not source.is_file():
        raise FileNotFoundError(f"OCR repair source does not exist: {source}")
    target = _repair_markdown_path(report.sidecar_path)
    work_root = target.parent / f".{target.stem}.layout-work"
    checkpoint = work_root / "checkpoint.json"
    if work_root.exists() and not checkpoint.is_file():
        raise ValueError(f"Layout repair workspace has no checkpoint: {work_root}")
    state_path = _layout_repair_state_path(report.sidecar_path)
    layout = json.loads(state_path.read_text(encoding="utf-8"))
    if not isinstance(layout, dict):
        raise ValueError(f"Layout repair state must be an object: {state_path}")

    actual_signature = _source_signature(source)
    recorded_signature = layout.get("source_signature")
    if not _source_signature_is_compatible(recorded_signature, actual_signature):
        raise ValueError(
            f"Source signature changed for {source}; refusing checkpoint repair"
        )
    layout["source"] = str(source)
    layout["source_signature"] = actual_signature

    pages = {
        int(page.get("page_number", position)): page
        for position, page in enumerate(layout.get("pages", []), start=1)
        if isinstance(page, dict)
    }
    archived_regions: set[tuple[int, int]] = set()
    for proposal in proposals:
        if proposal.scope != "region":
            continue
        page = pages.get(int(proposal.page_number or 0))
        if page is None:
            raise ValueError(f"Repair page is missing for {proposal}")
        region = next(
            (
                item
                for item in page.get("regions", [])
                if isinstance(item, dict)
                and int(item.get("index", -1)) == proposal.region_index
            ),
            None,
        )
        if region is None:
            raise ValueError(f"Repair region is missing for {proposal}")
        region_key = (
            int(proposal.page_number or 0),
            int(proposal.region_index or 0),
        )
        if (
            proposal.action in _OCR_REGION_MUTATING_ACTIONS
            and region_key not in archived_regions
        ):
            _append_layout_repair_history(region, proposal)
            archived_regions.add(region_key)
        if (
            proposal.action in _OCR_SELECTIVE_REPROCESS_ACTIONS
            and region.get("status") in _OCR_TERMINAL_REGION_STATUSES
        ):
            region.update(
                status="pending",
                raw_content="",
                content="",
                error=None,
                recovery=None,
                finish_reason=None,
            )
        if proposal.action == "review_or_discard":
            if str(region.get("label")) not in {"header", "footer", "number"}:
                raise ValueError(
                    f"automatic discard is limited to decorative regions: {proposal}"
                )
            if str(region.get("content") or "").strip():
                raise ValueError(
                    f"automatic discard requires an empty region: {proposal}"
                )
            region.update(
                status="recovered",
                raw_content="",
                content="",
                error=None,
                recovery=(
                    "Discarded a degenerate Unlimited-OCR response for a "
                    "decorative or empty number region"
                ),
                finish_reason="stop",
            )
        if proposal.action == "adjust_crop_and_retry":
            region["status"] = "failed"
            region["error"] = (
                "ValueError: Unlimited-OCR output is empty after post-processing"
            )
        page["status"] = "partial"

    resume_proposals = [
        proposal
        for proposal in proposals
        if proposal.scope == "file" and proposal.action == "resume_document"
    ]
    if resume_proposals:
        resume_reasons = tuple(
            dict.fromkeys(
                reason
                for proposal in resume_proposals
                for reason in proposal.reasons
            )
        )
        resume_proposal = resume_proposals[0]
        for page_number, page in pages.items():
            for region in page.get("regions", []):
                if not isinstance(region, dict):
                    continue
                try:
                    region_key = (page_number, int(region.get("index", -1)))
                except (TypeError, ValueError):
                    continue
                if (
                    region.get("status") not in _OCR_TERMINAL_REGION_STATUSES
                    and region_key not in archived_regions
                ):
                    _append_layout_repair_history(
                        region, resume_proposal, reasons=resume_reasons
                    )
                    archived_regions.add(region_key)
    layout["status"] = "partial"
    created_workspace = state_path == report.sidecar_path
    try:
        final_assets = target.parent / f"{target.stem}.assets"
        staged_assets = work_root / final_assets.name
        if created_workspace:
            if final_assets.is_dir():
                _clone_repair_assets(final_assets, staged_assets)
            else:
                staged_assets.mkdir(parents=True)
        _write_repair_json(checkpoint, layout)
        published = json.loads(
            report.sidecar_path.read_text(encoding="utf-8")
        )
        if not isinstance(published, dict):
            raise ValueError(
                f"Published layout sidecar must be an object: {report.sidecar_path}"
            )
        published["status"] = "partial"
        published["repair_checkpoint"] = str(checkpoint)
        _write_repair_json(report.sidecar_path, published)
    except Exception:
        if created_workspace and work_root.exists():
            shutil.rmtree(work_root)
        raise
    return layout


async def execute_ocr_repair_round(
    ocr_repair_queue: Sequence[OCRFileQualityReport],
    handlers: Mapping[OCRFixAction, OCRRepairHandler],
    *,
    proposals: Sequence[OCRFixProposal] | None = None,
    dry_run: bool = False,
    show_progress: bool = True,
    stream_reports: bool = True,
    _progress_position: int = 0,
    _round_number: int | None = None,
) -> OCRRepairRoundResult:
    """Execute registered proposal handlers once, then re-audit queued files.

    A handler receives one report plus every proposal for that file that maps to
    the same callback. This lets a provider resume a document once instead of
    issuing one expensive OCR call per failed region. Exceptions are retained in
    the attempt log and do not prevent other files from being repaired.

    Actions without a registered handler are explicitly marked ``skipped`` and
    remain in ``remaining_proposals`` after the recheck. ``dry_run`` performs the
    full dispatch preview and audit without invoking any handler. Set
    ``show_progress=False`` to suppress the per-file progress bar. Set
    ``stream_reports=False`` to suppress persistent per-file result lines.
    """
    reports = sorted(
        ocr_repair_queue, key=lambda report: str(report.sidecar_path).casefold()
    )
    selected_proposals = list(
        proposals if proposals is not None else propose_ocr_repairs(reports)
    )
    proposals_by_sidecar: dict[Path, list[OCRFixProposal]] = {
        report.sidecar_path.resolve(): [] for report in reports
    }
    for proposal in selected_proposals:
        sidecar = proposal.sidecar_path.expanduser().resolve()
        if sidecar in proposals_by_sidecar:
            proposals_by_sidecar[sidecar].append(proposal)

    attempts: list[OCRRepairAttempt] = []
    report_progress = tqdm(
        total=len(reports),
        desc="OCR repair files",
        unit="file",
        position=_progress_position,
        leave=False,
        dynamic_ncols=True,
        disable=not show_progress,
    )
    for report_number, report in enumerate(reports, start=1):
        attempt_start = len(attempts)
        report_progress.set_postfix_str(report.sidecar_path.name, refresh=True)
        report_proposals = proposals_by_sidecar[report.sidecar_path.resolve()]
        groups, unsupported = _handler_groups(report_proposals, handlers)
        if unsupported:
            unsupported_actions = tuple(
                dict.fromkeys(proposal.action for proposal in unsupported)
            )
            attempts.append(
                OCRRepairAttempt(
                    sidecar_path=report.sidecar_path,
                    actions=unsupported_actions,
                    proposal_count=len(unsupported),
                    status="skipped",
                    message="No handler is registered; proposals remain queued.",
                )
            )
        for handler, grouped_proposals in groups:
            actions = tuple(
                dict.fromkeys(proposal.action for proposal in grouped_proposals)
            )
            if dry_run:
                attempts.append(
                    OCRRepairAttempt(
                        sidecar_path=report.sidecar_path,
                        actions=actions,
                        proposal_count=len(grouped_proposals),
                        status="dry_run",
                        message="Handler dispatch previewed without execution.",
                    )
                )
                continue
            try:
                message = await handler(report, tuple(grouped_proposals))
            except Exception as error:
                attempts.append(
                    OCRRepairAttempt(
                        sidecar_path=report.sidecar_path,
                        actions=actions,
                        proposal_count=len(grouped_proposals),
                        status="failed",
                        message="Repair handler failed; findings remain queued.",
                        error=f"{type(error).__name__}: {error}",
                    )
                )
            else:
                attempts.append(
                    OCRRepairAttempt(
                        sidecar_path=report.sidecar_path,
                        actions=actions,
                        proposal_count=len(grouped_proposals),
                        status="completed",
                        message=message or "Repair handler completed.",
                    )
                )
        report_progress.update(1)
        if stream_reports:
            report_attempts = attempts[attempt_start:]
            attempt_counts = _repair_progress_counts(
                [attempt.status for attempt in report_attempts]
            )
            handler_results = " | ".join(
                (
                    f"{attempt.message} Error: {attempt.error}"
                    if attempt.error
                    else attempt.message
                )
                for attempt in report_attempts
            )
            try:
                live_report = audit_layout_ocr_file(report.sidecar_path)
                live_proposals = propose_ocr_repairs([live_report])
            except Exception as error:
                tqdm.write(
                    f"[OCR repair file {report_number}/{len(reports)}] "
                    f"{report.sidecar_path.name}: live audit failed: "
                    f"{type(error).__name__}: {error}"
                )
            else:
                issues_before = _repair_issue_count([report])
                issues_after = _repair_issue_count([live_report])
                progress_state = (
                    "progress"
                    if issues_after < issues_before
                    else "no_progress"
                    if issues_after == issues_before
                    else "regressed"
                )
                remaining_counts = _repair_progress_counts(
                    [proposal.action for proposal in live_proposals]
                )
                round_label = (
                    f" round {_round_number}" if _round_number is not None else ""
                )
                tqdm.write(
                    f"[OCR repair{round_label} file {report_number}/{len(reports)} "
                    f"{progress_state}] {report.sidecar_path.name}: "
                    f"handlers={attempt_counts or 'none'}; "
                    f"audit_issues={issues_before}->{issues_after}; "
                    f"remaining={remaining_counts or 'none'}; "
                    f"handler_results={handler_results or 'none'}"
                )
    report_progress.close()

    rechecked_reports = tuple(
        audit_layout_ocr_file(report.sidecar_path) for report in reports
    )
    remaining_queue = tuple(
        report for report in rechecked_reports if report.needs_repair
    )
    remaining_proposals = tuple(propose_ocr_repairs(remaining_queue))
    return OCRRepairRoundResult(
        attempts=tuple(attempts),
        rechecked_reports=rechecked_reports,
        remaining_queue=remaining_queue,
        remaining_proposals=remaining_proposals,
        issues_before=_repair_issue_count(reports),
        issues_after=_repair_issue_count(remaining_queue),
    )


async def execute_ocr_repairs_until_stable(
    root: str | Path,
    handlers: Mapping[OCRFixAction, OCRRepairHandler],
    *,
    max_rounds: int = 3,
    dry_run: bool = False,
    include_partial_checkpoints: bool = False,
    partial_documents_only: bool = False,
    show_progress: bool = True,
    stream_reports: bool = True,
) -> OCRRepairLoopResult:
    """Execute, re-audit, and requeue repairs until clean or safely stopped.

    Unless ``show_progress`` is false, display nested bars for repair rounds and
    the files handled by the current round. Unless ``stream_reports`` is false,
    also emit a persistent result line as each file finishes. Set
    ``partial_documents_only`` to keep advisory findings in already processed
    documents from broadening a partial-output repair run.
    """
    if max_rounds <= 0:
        raise ValueError("max_rounds must be greater than zero")
    queue = tuple(
        report
        for report in collect_ocr_repair_queue(
            root, include_partial_checkpoints=include_partial_checkpoints
        )
        if not partial_documents_only or report.document_status == "partial"
    )
    if not queue:
        return OCRRepairLoopResult((), (), (), "clean")

    rounds: list[OCRRepairRoundResult] = []
    stop_reason: OCRRepairStopReason = "max_rounds"
    round_progress = tqdm(
        total=max_rounds,
        desc="OCR repair rounds",
        unit="round",
        position=0,
        dynamic_ncols=True,
        disable=not show_progress,
    )
    for round_number in range(1, max_rounds + 1):
        round_progress.set_postfix(
            round=round_number,
            queued=len(queue),
            refresh=True,
        )
        round_result = await execute_ocr_repair_round(
            queue,
            handlers,
            dry_run=dry_run,
            show_progress=show_progress,
            stream_reports=stream_reports,
            _progress_position=1,
            _round_number=round_number,
        )
        rounds.append(round_result)
        queue = tuple(
            report
            for report in round_result.remaining_queue
            if not partial_documents_only
            or report.document_status == "partial"
        )
        round_progress.update(1)
        round_progress.set_postfix(
            queued=len(queue),
            issues=f"{round_result.issues_before}->{round_result.issues_after}",
            refresh=True,
        )
        if not queue:
            stop_reason = "clean"
            break
        if dry_run:
            stop_reason = "dry_run"
            break
        completed = any(
            attempt.status == "completed" for attempt in round_result.attempts
        )
        if not completed:
            stop_reason = (
                "execution_failed"
                if any(
                    attempt.status == "failed"
                    for attempt in round_result.attempts
                )
                else "no_handlers"
            )
            break
        if round_result.issues_after >= round_result.issues_before:
            stop_reason = "no_progress"
            break

    round_progress.set_postfix(
        stop=stop_reason,
        queued=len(queue),
        refresh=True,
    )
    round_progress.close()
    remaining_proposals = tuple(propose_ocr_repairs(queue))
    if stream_reports:
        tqdm.write(
            f"[OCR repair stop={stop_reason}] rounds={len(rounds)}/{max_rounds}; "
            f"queued={len(queue)}; remaining={len(remaining_proposals)}"
        )
    return OCRRepairLoopResult(
        rounds=tuple(rounds),
        remaining_queue=queue,
        remaining_proposals=remaining_proposals,
        stop_reason=stop_reason,
    )
